function levelInfo(xp) {
  let i = 0; LEVELS.forEach((l, k) => { if (xp >= l.xp) i = k; });
  const cur = LEVELS[i], next = LEVELS[i + 1] || null;
  return { i, cur, next, pct: next ? Math.round((xp - cur.xp) / (next.xp - cur.xp) * 100) : 100, toNext: next ? next.xp - xp : 0 };
}
