  const pct = Math.round((m.progress || 0) * 100);
  const el = $('ocr-progress'); el.classList.remove('hidden'); el.value = pct;
  setStatus('📖 ' + (OCR_STEPS[m.status] || 'Lavoro…') + (m.status === 'recognizing text' ? ` ${pct}%` : ''));
